/// <reference types="react" />
export type TaxonomyValues = Record<string, 'on' | 'off'>;
export type TaxonomyOptions = Record<string, Record<'label', string>>;
export type OnSaveClickParams = {
    moduleNameOption: string;
    saveToDiviCloudOption: string;
    saveAsGlobalOption: string;
    addCategoryNameOption: string;
    addTagNameOption: string;
    selectedCategories: string[];
    selectedTags: string[];
    optionsContainerRef: React.MutableRefObject<HTMLDivElement>;
};
export interface Props {
    onSaveClick: (params: OnSaveClickParams) => void;
    onHelpClick?: () => void;
    moduleName: string;
    moduleType: string;
    saveToDiviCloud: string;
    saveAsGlobal: string;
    hasSaveAsGlobal: boolean;
    addCategoryName: string;
    addTagName: string;
    owner: string;
    hasSubmitError: boolean;
    category: {
        options: TaxonomyOptions;
        values: TaxonomyValues;
    };
    tag: {
        options: TaxonomyOptions;
        values: TaxonomyValues;
    };
    topWindowHeight: number;
    modalDimension: Record<string, number>;
    modalOffset: Record<string, number>;
}
export interface Result {
    layoutData: {
        edit_link: string;
        post_id: string;
    };
    updatedTerms: {
        layout_category: Array<string>;
        layout_tag: Array<string>;
    };
}
